import React from "react";

const Operator = ({ symbol, className = "" }) => (
  <table className={`opertor ${className}`}>
    <tbody>
      <tr>
        <td>
          <h2>{symbol}</h2>
        </td>
      </tr>
    </tbody>
  </table>
);
export default Operator;
